/**
 * @name Dangerous use of markupsafe.Markup with unescaped input
 * @description Detects flows from remote (user-controlled) data into markupsafe.Markup() or .escape() usage that may be misused for XSS if treated as already-safe HTML.
 * @kind path-problem
 * @problem.severity warning
 * @id py/markupsafe-unescaped-input
 * @tags security
 *       external/cwe/cwe-079
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module MarkupTaintConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("markupsafe").getMember(["Markup", "escape"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module MarkupTaintFlow = TaintTracking::Global<MarkupTaintConfig>;
import MarkupTaintFlow::PathGraph

from MarkupTaintFlow::PathNode source, MarkupTaintFlow::PathNode sink
where MarkupTaintFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "User-controlled data reaches markupsafe.$@ without prior escaping.", source.getNode(), "user input"

/**
 * @name Direct Markup construction from remote input
 * @description Detects flows from remote data sources into markupsafe.Markup constructor without escaping.
 * @kind path-problem
 * @problem.severity error
 * @id py/markupsafe-remote-to-markup
 * @tags security
 *       external/cwe/cwe-079
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module RemoteToMarkupConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(API::CallNode mkCall |
      mkCall = API::moduleImport("markupsafe").getMember("Markup").getACall() |
      sink = mkCall.getArg(0)
    )
  }
}

module RemoteToMarkupFlow = TaintTracking::Global<RemoteToMarkupConfig>;
import RemoteToMarkupFlow::PathGraph

from RemoteToMarkupFlow::PathNode source, RemoteToMarkupFlow::PathNode sink
where RemoteToMarkupFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "User-controlled data flows into markupsafe.Markup without escaping, which can cause XSS.", source.getNode(), "remote input"
